import { parseVerdeler, type Verdeler } from './model.ts';

/**
 * Verdelers: the floor heating manifold, loop by loop.
 *
 * 'O' a loop that is flowing, '.' one that is shut, '#' a loop with no valve
 * on it — those sit on the manifold and get dragged about by their
 * neighbours, and there is nothing you can do with them directly.
 *
 * Generated by starting balanced and turning valves at random, so each is
 * solvable by construction.
 *
 * PROVISIONAL: which loop feeds which room comes with the real drawings.
 */

export type VerdelerLevel = {
  readonly id: string;
  readonly ruimte: string;
  readonly titel: string;
  readonly praatje: string;
  readonly uitleg: readonly string[];
  readonly verdeler: Verdeler;
};

const UITLEG_EERSTE = [
  'DE VLOERVERWARMING. ELKE LUS LOOPT OVER DEZELFDE VERDELER, DUS ZE PIKKEN ELKAARS DRUK IN.',
  'DRAAI JE EEN KRAAN OPEN, DAN SLAAN DE LUSSEN ERNAAST JUIST DICHT. EN ANDERSOM.',
  'ALLES MOET TEGELIJK OPEN. DAT IS INREGELEN. VEEL GELUK.',
];

const UITLEG_LATER = [
  'VOLGENDE VERDELER. MEER LUSSEN, EN EEN PAAR ZONDER KRAAN.',
  'DIE GRIJZE HEBBEN GEEN KRAAN: DIE VOLGEN ALLEEN HUN BUREN. ALLES OPEN, ZOALS NET.',
];

export const VERDELER_LEVELS: readonly VerdelerLevel[] = [
  {
    id: 'verdeler-woonkamer',
    ruimte: 'WOONKAMER',
    titel: 'VERDELER WOONKAMER',
    praatje: 'VIER BIJ DRIE. ALLE LUSSEN OPEN.',
    uitleg: UITLEG_EERSTE,
    verdeler: parseVerdeler([
      '.O.O',
      '.OOO',
      'O.OO',
    ]),
  },
  {
    id: 'verdeler-keuken',
    ruimte: 'KEUKEN',
    titel: 'VERDELER KEUKEN',
    praatje: 'EEN LUS ZONDER KRAAN. DIE DOET WAT DE BUREN DOEN.',
    uitleg: UITLEG_LATER,
    verdeler: parseVerdeler([
      '..OO#',
      'O.O.O',
      '..O.O',
      '.O.O.',
    ]),
  },
  {
    id: 'verdeler-tvkamer',
    ruimte: 'TV-KAMER',
    titel: 'VERDELER TV-KAMER',
    praatje: 'DE GROTE. TWEE ZONDER KRAAN.',
    uitleg: UITLEG_LATER,
    verdeler: parseVerdeler([
      '.....',
      'OO.OO',
      'O#...',
      '#..O.',
      '...O.',
    ]),
  },
];
